-- What's new for the 2026-11-12 Project Setup / status / closeout release,
-- published when the migration runs (the deploy). Staff can edit or unpublish
-- them on Help, Feedback & notes (#/help-admin).
INSERT INTO release_notes (title, body, page, tour_key, capability, published_at, created_by)
SELECT * FROM (
  SELECT 'Project Setup: every live project, one step per card' AS title, 'Project Setup now has To do (new jobs being set up, plus projects a change sent back) and All active (every live project, to edit in place). Each card does one thing: the PO (drop it in, or say why there isn''t one yet), the estimate, the first invoice with its expected pay date, the dates, the PM, the crew and offer, the job details, and each schedule on its own. Open in Pipeline shows the pipeline record without leaving.' AS body, '#/setup' AS page, '#/setup' AS tour_key, 'page.assignment' AS capability, NOW() - INTERVAL 0 SECOND AS published_at, 'release-1112b' AS created_by
  UNION ALL SELECT 'Changes send a project back for re-review', 'When a set-up project''s dates move, a change order comes in, or the crew or the contract value changes, it goes back to Project Setup and only the affected steps reopen (shown in red). For a date change the app asks why it moved and whether a change order is needed. Then press Reviewed. Every date change is kept in the job''s date history.', '#/setup', '#/setup', 'page.assignment', NOW() - INTERVAL 1 SECOND, 'release-1112b'
  UNION ALL SELECT 'Status follows the job', 'A project''s status is worked out, not picked: Setup, Ready, In progress, Closing (ended, books still open) and Closed. On hold and Canceled are the only ones a person sets, from the job''s Assignment (Hold, Cancel, Restore). The status dropdowns are gone.', '#/projects', '#/projects', 'page.customers', NOW() - INTERVAL 2 SECOND, 'release-1112b'
  UNION ALL SELECT 'Bell alerts for the whole office', 'Everyone in the office now hears about date, crew and PM changes, change orders, projects sent back to setup, and setup notes (no PO yet, estimate not done, first invoice not sent). Switch any of them off in the bell''s settings.', NULL, NULL, 'page.assignment', NOW() - INTERVAL 3 SECOND, 'release-1112b'
  UNION ALL SELECT 'Closeout: every finished job gets reviewed', 'Project Closeout keeps every finished job until it''s closed out: jobs that ended since Oct 1, older jobs with money or a change order still open, and older jobs with only paperwork gaps. Every job gets the 100% sign-off and the margin review. Owners can close out a whole list at once with one note.', '#/closeout', '#/closeout', 'page.assignment', NOW() - INTERVAL 4 SECOND, 'release-1112b'
  UNION ALL SELECT 'Crew offers and availability', 'Record a crew offer that was sent outside the app (sent and accepted dates, plus the signed offer). An offer sent from the app needs the crew payment schedule first. Crew availability now works for jobs longer than six months, by week.', '#/setup', NULL, 'page.assignment', NOW() - INTERVAL 5 SECOND, 'release-1112b'
) d
WHERE NOT EXISTS (SELECT 1 FROM release_notes WHERE created_by = 'release-1112b');
